// The third polygon: a synthetic upstream in the shape of an Eclipse Theia
// monorepo (FEAT-001 ##POLYGON-THEIA-IS-SYNTHETIC, PROP-016 ##TYPE-THEIA).
//
// It is a small git repository generated by code, and it repeats the shape of
// upstream Theia that matters to codkit and nothing else: one npm workspace
// whose root manifest is `@theia/monorepo`, a `lerna.json` that carries the one
// version of the tree, a framework package that binds a service, an application
// that is a `package.json` with a `theia` section and a dependency inventory,
// and the two upstream sources the upgrade advisory reads. There is no
// `node_modules` and nothing is ever compiled here: the polygon proves the model
// of the type, not Theia.
//
// The history is what an upgrade of this family has to survive:
//
//   c1 (anchor, root)                                the commit ##ID-CHECK-ORIGIN looks for
//   c2  the framework package and the application -> v1.75.0  "old pin"
//   c3  an edit inside the framework package, away from the seam
//   c4  the version of the monorepo moves, an entry kind is added -> v1.76.0  "new pin"
//
// Everything is deterministic: fixed author, fixed committer, fixed dates one
// minute apart, so the commit shas are identical on every machine and run.

import { chmodSync, mkdirSync } from 'node:fs';
import { fixtureCommit, fixtureGit } from './makeUpstream.ts';
import type { UpstreamRef } from './makeUpstream.ts';
import { writeBytes } from './patchText.ts';

export type TheiaUpstreamFixture = {
	/** Absolute path of the generated work tree. */
	readonly dir: string;
	/** Root commit: what PROP-008 ##ID-CHECK-ORIGIN checks for. */
	readonly anchorSha: string;
	readonly v1: UpstreamRef;
	readonly v2: UpstreamRef;
};

/** ##THEIA-VERSION-SOURCE: the version of the monorepo, and where it is written. */
export const OLD_VERSION = '1.75.0';
export const NEW_VERSION = '1.76.0';

/** The application directory of the polygon: an example the product forks. */
export const APPLICATION_ROOT = 'examples/electron';
/** The overlay target of the type: the application's manifest. */
export const APPLICATION_MANIFEST = `${APPLICATION_ROOT}/package.json`;
/** The framework package that binds the service the own package rebinds. */
export const CORE_MODULE_PATH = 'packages/core/src/browser/core-frontend-module.ts';
/** Where the service identifier the own package imports is declared. */
export const CORE_SERVICE_PATH = 'packages/core/src/browser/editor-manager.ts';
/** The upstream source the advisory reads the entry kinds from. */
export const EXTENSION_PACKAGE_PATH = 'dev-packages/application-package/src/extension-package.ts';
/** The upstream source the advisory reads the manifest schema from. */
export const APPLICATION_PROPS_PATH = 'dev-packages/application-package/src/application-props.ts';

const FIRST_COMMIT_ISO = '2026-04-01T00:00:00Z';

export function makeTheiaUpstream(dir: string): TheiaUpstreamFixture {
	mkdirSync(dir, { recursive: true });
	fixtureGit(dir, ['init', '--quiet', '--initial-branch=main', '.']);

	let clock = 0;
	writeAll(dir, rootFiles());
	const anchorSha = fixtureCommit(dir, 'fixture: the monorepo and its tooling', commitDate(clock));
	clock += 1;

	writeAll(dir, workspaceFiles(OLD_VERSION));
	const v1Date = commitDate(clock);
	const v1Sha = fixtureCommit(dir, 'fixture: the framework package and the example application', v1Date);
	fixtureGit(dir, ['tag', `v${OLD_VERSION}`]);
	clock += 1;

	// c3: an edit inside the framework package, far away from the seam the own
	// package rebinds.
	writeBytes(`${dir}/${CORE_MODULE_PATH}`, coreModuleAfterEdit());
	fixtureCommit(dir, 'fixture: name the frontend module in its header', commitDate(clock));
	clock += 1;

	// c4: the version of the monorepo moves and an entry kind is added - the two
	// changes the advisory of this family has an opinion about. Only the files
	// that carry the version are rewritten: the sources keep the c3 edit, which
	// is what makes the patch of a delta land shifted rather than clean.
	writeAll(dir, versionedFiles(NEW_VERSION));
	writeBytes(`${dir}/${EXTENSION_PACKAGE_PATH}`, extensionPackageTs(true));
	const v2Date = commitDate(clock);
	const v2Sha = fixtureCommit(dir, 'fixture: release the next version of the monorepo', v2Date);
	fixtureGit(dir, ['tag', `v${NEW_VERSION}`]);

	return {
		dir,
		anchorSha,
		v1: { tag: `v${OLD_VERSION}`, sha: v1Sha, dateIso: v1Date },
		v2: { tag: `v${NEW_VERSION}`, sha: v2Sha, dateIso: v2Date }
	};
}

function commitDate(minute: number): string {
	return new Date(Date.parse(FIRST_COMMIT_ISO) + minute * 60_000).toISOString().replace('.000Z', 'Z');
}

function writeAll(dir: string, files: ReadonlyMap<string, string>): void {
	for (const [relative, content] of files) {
		writeBytes(`${dir}/${relative}`, content);
		if (relative.endsWith('.mjs')) {
			chmodSync(`${dir}/${relative}`, 0o755);
		}
	}
}

/** What the anchor commit carries: the monorepo itself and its stub runners. */
function rootFiles(): ReadonlyMap<string, string> {
	return new Map<string, string>([
		['.gitignore', GITIGNORE],
		['README.md', README],
		['package.json', rootManifest()],
		['lerna.json', lernaJson(OLD_VERSION)],
		['build/stub-step.mjs', STUB_STEP],
		['build/stub-own.mjs', STUB_OWN],
		['build/stub-watch.mjs', STUB_WATCH],
		[EXTENSION_PACKAGE_PATH, extensionPackageTs(false)],
		[APPLICATION_PROPS_PATH, APPLICATION_PROPS_TS]
	]);
}

/** The packages of the workspace, at one version of the monorepo. */
function workspaceFiles(version: string): ReadonlyMap<string, string> {
	return new Map<string, string>([...versionedFiles(version), [CORE_SERVICE_PATH, CORE_SERVICE_TS], [CORE_MODULE_PATH, CORE_MODULE_TS]]);
}

/** The files that carry the version of the monorepo, and nothing else. */
function versionedFiles(version: string): ReadonlyMap<string, string> {
	return new Map<string, string>([
		['lerna.json', lernaJson(version)],
		['package-lock.json', packageLock(version)],
		['packages/core/package.json', coreManifest(version)],
		[APPLICATION_MANIFEST, applicationManifest(version)]
	]);
}

const GITIGNORE = `node_modules/
lib/
src-gen/
.eslintcache
*.tsbuildinfo
.fixture/
`;

const README = `# fixture-theia-monorepo

A synthetic upstream in the shape of an Eclipse Theia monorepo: one npm
workspace, one version in lerna.json, a framework package that binds a service,
and an application that is a package.json. Nothing here is compiled - the
polygon proves the model of the project type, not the framework.
`;

/**
 * ##THEIA-TREE-FINGERPRINT: the root manifest of this family, with the
 * workspace globs a package of the tree may live under. The scripts are the
 * fixture counterparts of upstream's own: the full-tree lint of the hygiene
 * step, and the two watch channels of ##THEIA-BUILD-CHANNELS, which print the
 * verbatim pass boundaries of `tsc -b -w` and of upstream's esbuild problem
 * matcher.
 */
function rootManifest(): string {
	return `${JSON.stringify(
		{
			private: true,
			name: '@theia/monorepo',
			version: '0.0.0',
			engines: { node: '>=24' },
			workspaces: ['dev-packages/*', 'packages/*', 'examples/*'],
			scripts: {
				lint: 'node build/stub-step.mjs lint',
				'watch:compile': 'node build/stub-watch.mjs typecheck',
				'watch:bundle': 'node build/stub-watch.mjs bundle'
			}
		},
		null,
		2
	)}\n`;
}

function lernaJson(version: string): string {
	return `${JSON.stringify({ $schema: 'node_modules/lerna/schemas/lerna-schema.json', npmClient: 'npm', version }, null, 2)}\n`;
}

function coreManifest(version: string): string {
	return `${JSON.stringify(
		{
			name: '@theia/core',
			version,
			theiaExtensions: [{ frontend: 'lib/browser/core-frontend-module' }],
			scripts: { lint: 'theiaext lint', compile: 'theiaext compile', test: 'theiaext test' }
		},
		null,
		2
	)}\n`;
}

/**
 * ##THEIA-OVERLAY-TARGET: an application of this family is a `package.json` -
 * the `theia` section carries the identity and the preference defaults, and the
 * `dependencies` list is the whole extension inventory.
 */
function applicationManifest(version: string): string {
	return `${JSON.stringify(
		{
			private: true,
			name: '@theia/example-electron',
			version,
			productName: 'Theia Electron Example',
			main: 'lib/backend/electron-main.js',
			theia: {
				target: 'electron',
				frontend: { config: { applicationName: 'Theia Electron Example', reloadOnReconnect: true } },
				backend: { config: { frontendConnectionTimeout: -1 } }
			},
			dependencies: { '@theia/core': version },
			devDependencies: { electron: '42.8.1' }
		},
		null,
		2
	)}\n`;
}

/** The lockfile, which is where every workspace package of the tree is named. */
function packageLock(version: string): string {
	return `${JSON.stringify(
		{
			name: '@theia/monorepo',
			lockfileVersion: 3,
			requires: true,
			packages: {
				'': { name: '@theia/monorepo', version: '0.0.0', workspaces: ['dev-packages/*', 'packages/*', 'examples/*'] },
				'packages/core': { name: '@theia/core', version },
				'examples/electron': { name: '@theia/example-electron', version },
				'node_modules/@theia/core': { resolved: 'packages/core', link: true }
			}
		},
		null,
		2
	)}\n`;
}

/** The service identifier the own package of the patch set rebinds. */
const CORE_SERVICE_TS = `// The editor manager of the fixture framework.

export class EditorManager {
	open(uri: string): string {
		return 'upstream:' + uri;
	}
}
`;

/** The container module of the framework package: this is what binds the service. */
const CORE_MODULE_TS = `// The frontend module of the fixture framework package.

import { ContainerModule } from '@theia/core/shared/inversify';
import { EditorManager } from './editor-manager';

export default new ContainerModule(bind => {
	bind(EditorManager).toSelf().inSingletonScope();
});
`;

/**
 * The edit of c3: a line added at the top of the framework's container module,
 * away from the block the patch of the delta owns. It costs the patch its
 * exact line numbers - the outcome the upgrade cycle calls `shifted` - and
 * nothing else.
 */
function coreModuleAfterEdit(): string {
	return CORE_MODULE_TS.replace(
		'// The frontend module of the fixture framework package.\n',
		'// The frontend module of the fixture framework package.\n// It is the one every application of the fixture loads first.\n'
	);
}

/**
 * ##THEIA-ADVISORY-READERS: the entry kinds a `theiaExtensions` array may
 * declare. The second pin adds one, which is exactly the kind of change the
 * advisory of this family exists to name.
 */
function extensionPackageTs(withSecondaryWindow: boolean): string {
	const extra = withSecondaryWindow ? '    secondaryWindow?: string;\n' : '';
	return `// The extension package of the fixture framework.

export interface Extension {
    frontend?: string;
    frontendElectron?: string;
${extra}    backend?: string;
    electronMain?: string;
}

export interface ExtensionPackageOptions {
    alias?: string;
}
`;
}

/** ##THEIA-ADVISORY-READERS: the schema of the `theia` section of a manifest. */
const APPLICATION_PROPS_TS = `// The application properties of the fixture framework.

export interface FrontendApplicationConfig {
    readonly applicationName?: string;
    readonly defaultIconTheme?: string;
    readonly reloadOnReconnect?: boolean;
}

export interface BackendApplicationConfig {
    readonly frontendConnectionTimeout?: number;
}

export interface ApplicationProps {
    readonly target: string;
    readonly frontend: { readonly config: FrontendApplicationConfig };
    readonly backend: { readonly config: BackendApplicationConfig };
}
`;

/**
 * The fixture counterpart of the full-tree lint of this family. It asserts the
 * ordering PROP-011 fixes - the gates of the upstream see the application
 * manifest as the pin left it, before any overlay is materialized - and it can
 * be made red on demand, which is how the polygon proves a stop of the cycle.
 */
const STUB_STEP = `#!/usr/bin/env node
import { appendFileSync, mkdirSync, readFileSync } from 'node:fs';

const step = process.argv[2];
const manifest = JSON.parse(readFileSync('examples/electron/package.json', 'utf8'));
mkdirSync('.fixture', { recursive: true });
appendFileSync('.fixture/steps.log', step + '\\n', 'utf8');

if (manifest.theia.frontend.config.applicationName !== 'Theia Electron Example') {
	console.error(step + ': the application manifest was materialized before the upstream gates');
	process.exit(1);
}
if (process.env.STUB_LINT_MODE === 'fail') {
	console.error(step + ': fixture lint failed');
	process.exit(1);
}
console.log(step + ': fixture lint passed before the overlay was materialized');
process.exit(0);
`;

/**
 * The fixture counterpart of `theiaext lint` and `theiaext test`: the scripts of
 * one package, run from that package's own directory by
 * `npm run <script> --workspace <ownRoot>`. It reads nothing of the tree - what
 * the ordering gate asserts is the business of the full-tree step - and it can
 * be made red on demand, which is how the polygon proves a stop of the cycle.
 */
const STUB_OWN = `#!/usr/bin/env node
const step = process.argv[2];
const mode = step === 'test' ? process.env.STUB_TEST_MODE : process.env.STUB_LINT_MODE;
if (mode === 'fail') {
	console.error('own ' + step + ': fixture ' + step + ' failed');
	process.exit(1);
}
console.log('own ' + step + ': fixture ' + step + ' passed');
process.exit(0);
`;

/**
 * The fixture counterparts of the two watch daemons of this family. Every line
 * is the verbatim shape the type declares as a pass boundary: the TypeScript
 * watch prints its own stamped summary, and the bundle channel prints the lines
 * of upstream's esbuild problem-matcher plugin.
 */
const STUB_WATCH = `#!/usr/bin/env node
const CHANNELS = {
	typecheck: {
		start: '[10:11:12 AM] Starting compilation in watch mode...',
		error: '[10:11:13 AM] packages/core/src/browser/editor-manager.ts(4,2): error TS2322: Type number is not assignable to type string.',
		end: (errors) => '[10:11:13 AM] Found ' + errors + ' errors. Watching for file changes.'
	},
	bundle: {
		start: '[watch/electron] Build started',
		error: 'X [ERROR] Could not resolve "./missing"',
		end: (errors) => '[watch/electron] Finished with ' + errors + ' errors in 812ms.'
	}
};

const channel = CHANNELS[process.argv[2]] ?? CHANNELS.typecheck;
const mode = process.env.STUB_WATCH_MODE || 'ok';

process.stdout.write(channel.start + '\\n');
if (mode === 'red') {
	process.stdout.write(channel.error + '\\n');
}
process.stdout.write(channel.end(mode === 'red' ? 1 : 0) + '\\n');
setInterval(() => {}, 60000);
`;
